module right_shifter(
    input clk,
    input d,
    output reg [7:0] q
);
    reg state;
    parameter state_0 = 0;
    initial begin
        q = 8'b00000000;
        state = state_0;
    end
    always @(posedge clk) begin
        case (state)
            state_0: begin
                q <= (q >> 1);
                q[7] <= d;
                state <= state_0;
            end
        endcase
    end
endmodule
